//go:build arm64

package floats

import "unsafe"

// The arm64 kernel of CMulTo (cmulto.go), generated by go-asmgen (cmulto_arm64_gen.go)
// into cmulto_arm64.s: the scalar loop of the complex product in assembly, steps of
// four complex numbers and the last ones one at a time, in one call. Not NEON: see the
// generator for why (go-simd/floats#81). Scalar FP is the ARMv8-A baseline: no gate.
// go:noescape.
//
//go:noescape
func cmulToFP(dst, a, b *float64, n int)

func cmulTo(dst, a, b []complex128) {
	if len(dst) > 0 {
		cmulToFP(f64ptr(&dst[0]), f64ptr(&a[0]), f64ptr(&b[0]), len(dst))
	}
}

func f64ptr(p *complex128) *float64 { return (*float64)(unsafe.Pointer(p)) }
